        if (reset) begin
            shift_ena <= 1'b1;
            count     <= 2'd1; // Since cycle 1 is happening now (on reset), we need 3 more cycles.
        end else begin
            if (count < 2'd3) begin
                count     <= count + 2'd1;
                shift_ena <= 1'b1;
            end else begin
                shift_ena <= 1'b0;
            end
